import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { ALL, CHAR_GROUPS } from './chars.ts';
import { HSK1 } from './hsk.ts';
import { PRESET_EXTRA_CHARS } from './presets.ts';
import { charFile } from '../domain/charFile.ts';

// Generated by `npm run data` (runs automatically before tests).
const DATA_DIR = path.resolve('public/hanzi');
const readData = (c: string) =>
  JSON.parse(fs.readFileSync(path.join(DATA_DIR, charFile(c)), 'utf8')) as {
    strokes: string[];
    medians: number[][][];
  };

// Guards the decks in src/data/decks (edited by hand) against typos and missing stroke data.
describe('decks', () => {
  it('has non-empty groups with unique names', () => {
    const names = CHAR_GROUPS.map((g) => g.name);
    expect(new Set(names).size).toBe(names.length);
    for (const g of CHAR_GROUPS) {
      expect(g.name).toBeTruthy();
      expect(g.items.length).toBeGreaterThan(0);
    }
  });

  it('has complete entries', () => {
    for (const it of ALL) {
      expect(it, JSON.stringify(it)).toMatchObject({
        c: expect.stringMatching(/^.$/u),
        py: expect.stringMatching(/\S/),
        en: expect.stringMatching(/\S/),
      });
    }
  });

  it('has no duplicate characters', () => {
    const chars = ALL.map((it) => it.c);
    const dups = chars.filter((c, i) => chars.indexOf(c) !== i);
    expect(dups).toEqual([]);
  });

  it('has a stroke data file for every character', () => {
    const missing = ALL.map((it) => it.c).filter(
      (c) => !fs.existsSync(path.join(DATA_DIR, charFile(c))),
    );
    expect(missing).toEqual([]);
    for (const { c } of ALL) {
      const d = readData(c);
      expect(d.strokes.length, c).toBeGreaterThan(0);
      expect(d.medians.length, c).toBe(d.strokes.length);
    }
  });

  it('has no orphan stroke data files', () => {
    const expected = new Set(
      [...ALL, ...HSK1, ...PRESET_EXTRA_CHARS].map((it) => charFile(it.c)),
    );
    const orphans = fs.readdirSync(DATA_DIR).filter((f) => !expected.has(f));
    expect(orphans).toEqual([]);
  });
});
